class Solution { public int stoneGameVII(int[] stones){int n=stones.length;int[] prefix=new int[n+1];for(int i=0;i<n;i++)prefix[i+1]=prefix[i]+stones[i];int[][] dp=new int[n][n];for(int length=2;length<=n;length++)for(int left=0;left+length<=n;left++){int right=left+length-1;int removeLeft=prefix[right+1]-prefix[left+1]-dp[left+1][right];int removeRight=prefix[right]-prefix[left]-dp[left][right-1];dp[left][right]=Math.max(removeLeft,removeRight);}return dp[0][n-1];} }
